// Some portions generated by Claude

// Plan task M8.1: the router intercepts links to router-ready routes, preloads the next route while the old page
// stays visible, lets a newer navigation abort an older one, and swaps the outlet in one step.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

const scripts = process.env.WORKBENCH_SCRIPT_DIR
    || path.resolve(__dirname, '../../tools/workbench/src/main/webapp/scripts');
const base = 'https://example.test/workbench/repositories/repo-1/';

function deferred() {
    let resolve;
    let reject;
    const promise = new Promise((yes, no) => { resolve = yes; reject = no; });
    return { promise, resolve, reject };
}

const settle = () => new Promise((resolve) => setImmediate(resolve));

/** A browser window with a history stack, as much as the router uses. */
function fakeWindow(href) {
    let current = href;
    const listeners = new Map();
    const win = {
        assigned: [],
        reloaded: 0,
        scrolledTo: [],
        scrollY: 0,
        location: {
            get href() { return current; },
            get origin() { return new URL(current).origin; },
            assign(url) { win.assigned.push(String(url)); },
            reload() { win.reloaded++; }
        },
        history: {
            scrollRestoration: 'auto',
            state: null,
            entries: [],
            pushState(state, title, url) {
                this.state = state;
                current = new URL(url, current).href;
                this.entries.push(['push', state, current]);
            },
            replaceState(state, title, url) {
                this.state = state;
                if (url !== undefined) {
                    current = new URL(url, current).href;
                }
                this.entries.push(['replace', state, current]);
            }
        },
        scrollTo(x, y) {
            win.scrollY = y;
            win.scrolledTo.push(y);
        },
        frames: 0,
        requestAnimationFrame(callback) {
            win.frames++;
            setTimeout(callback, 0);
        },
        addEventListener(type, handler) {
            listeners.set(type, (listeners.get(type) || []).concat([handler]));
        },
        removeEventListener(type, handler) {
            listeners.set(type, (listeners.get(type) || []).filter((other) => other !== handler));
        },
        listenerCount(type) { return (listeners.get(type) || []).length; },
        dispatch(type, event) { (listeners.get(type) || []).slice().forEach((handler) => handler(event)); },
        goTo(url, state) {
            current = new URL(url, current).href;
            win.history.state = state === undefined ? null : state;
        }
    };
    return win;
}

function fakeElement(attributes) {
    const values = Object.assign({}, attributes);
    return {
        attributes: values,
        setAttribute(name, value) { values[name] = String(value); },
        getAttribute(name) { return Object.prototype.hasOwnProperty.call(values, name) ? values[name] : null; },
        removeAttribute(name) { delete values[name]; },
        hasAttribute(name) { return Object.prototype.hasOwnProperty.call(values, name); }
    };
}

/** A link as the click handler sees it: href is the resolved URL, the attributes are as written. */
function link(href, attributes) {
    const anchor = fakeElement(Object.assign({ href }, attributes));
    anchor.href = new URL(href, base).href;
    return anchor;
}

function click(anchor, options) {
    const event = Object.assign({
        type: 'click', button: 0, ctrlKey: false, metaKey: false, shiftKey: false, altKey: false,
        defaultPrevented: false,
        target: { closest: (selector) => (selector === 'a[href]' ? anchor : null) },
        preventDefault() { this.defaultPrevented = true; }
    }, options || {});
    return event;
}

/**
 * The router loaded with the route registry and stand-ins for the page model loader and the views. Every
 * page model load waits until the test resolves it with answer(url, model) or fails it with fail(url, error).
 */
function loadRouter(options) {
    const settings = options || {};
    const window = fakeWindow(settings.href || base + 'summary');
    const documentListeners = new Map();
    const elements = {};
    const document = {
        title: 'Summary · repo-1 — RDF4J Workbench',
        elements,
        getElementById(id) { return elements[id] || null; },
        addEventListener(type, handler) {
            documentListeners.set(type, (documentListeners.get(type) || []).concat([handler]));
        },
        listenerCount(type) { return (documentListeners.get(type) || []).length; },
        dispatch(type, event) { (documentListeners.get(type) || []).forEach((handler) => handler(event)); }
    };
    window.document = document;
    const workbench = {};
    /** FormData over the fake forms of these tests: their fields, then the submitter's name and value. */
    class FakeFormData {
        constructor(form, submitter) {
            this.entries = (form.fields || []).slice();
            if (submitter && submitter.getAttribute('name')) {
                this.entries.push([submitter.getAttribute('name'), submitter.getAttribute('value') || '']);
            }
        }
        [Symbol.iterator]() { return this.entries[Symbol.iterator](); }
    }
    const consoleErrors = [];
    const recordingConsole = Object.assign(Object.create(console), {
        error: (...args) => consoleErrors.push(args)
    });
    const context = vm.createContext({ console: recordingConsole, URL, URLSearchParams, Promise, window, document,
        workbench, FormData: FakeFormData,
        setTimeout, clearTimeout, AbortController: settings.noAbortController ? undefined : AbortController });
    for (const filename of ['workbenchRoutes.js', 'workbenchRouter.js']) {
        const absolutePath = path.join(scripts, filename);
        vm.runInContext(fs.readFileSync(absolutePath, 'utf8'), context, { filename: absolutePath });
    }
    const outlet = fakeElement({ id: 'workbench-outlet' });
    const focused = [];
    const heading = fakeElement({ id: 'title_heading' });
    heading.focus = (focusOptions) => focused.push(focusOptions);
    outlet.querySelector = (selector) => (selector === 'h1' ? heading : null);
    elements['workbench-route-status'] = fakeElement({ id: 'workbench-route-status' });
    const mount = fakeElement({ id: 'workbench-app' });
    const log = [];
    const loads = new Map();
    const disposed = [];
    function pending(url) {
        if (!loads.has(url)) {
            loads.set(url, deferred());
        }
        return loads.get(url);
    }
    function model(viewId, extra) {
        return Object.assign({ viewId, vars: [], rows: [], rowStore: { dispose: () => disposed.push(viewId) } },
            extra || {});
    }
    const loadModelCalls = [];
    workbench.app = {
        loadModel(fetcher, url, signal) {
            loadModelCalls.push({ fetcher, url, signal });
            log.push('load ' + url.substring(base.length));
            return pending(url).promise;
        },
        completeModel(fetcher, url, loaded) { return Promise.resolve(loaded); },
        loadScripts(names) {
            log.push('scripts ' + names.join(','));
            return Promise.resolve();
        },
        configureNamespaces(loaded) { log.push('namespaces ' + loaded.viewId); },
        viewContext(appMount, loaded, url) { return { repositoryId: 'repo-1', url }; },
        renderFailure(appMount, error) { log.push('failure ' + error.message); }
    };
    workbench.views = {
        render(appMount, loaded) {
            log.push('render ' + loaded.viewId);
            document.title = loaded.title || document.title;
        },
        outletOf: () => outlet,
        bindContextBar() {
            log.push('bind context bar');
            return () => log.push('unbind context bar');
        }
    };
    const routes = workbench.routes;
    function register(viewId, routeOptions) {
        const extra = routeOptions || {};
        routes.register({
            viewId, routerReady: extra.routerReady !== false,
            scripts: () => extra.scripts || [], baseScripts: () => extra.baseScripts || [],
            mount(ctx) {
                log.push('mount ' + viewId);
                const instance = {
                    ready: extra.ready || Promise.resolve(),
                    dispose(reason) { log.push('dispose ' + viewId + ' ' + reason); }
                };
                return extra.mounted ? extra.mounted.then(() => instance) : instance;
            }
        });
    }
    ['summary', 'types', 'contexts', 'namespaces', 'explore', 'export'].forEach((viewId) => register(viewId));
    const fetched = [];
    const initial = {
        dispose(reason) { log.push('dispose initial ' + reason); }
    };
    const session = {
        mount, runtime: {}, basePath: '/workbench', url: window.location.href, model: model('summary'),
        instance: initial, fetcher: (url, fetchOptions) => { fetched.push({ url, fetchOptions }); },
        contextBar: () => log.push('unbind context bar')
    };
    return {
        window, document, workbench, router: workbench.router, outlet, mount, log, disposed, model, register,
        consoleErrors,
        session, fetched, loadModelCalls, focused, heading,
        status: elements['workbench-route-status'],
        answer(url, loaded) { pending(base + url).resolve(loaded); return settle(); },
        fail(url, error) { pending(base + url).reject(error); return settle(); },
        start() { workbench.router.start(session); }
    };
}

test('the router loads on its own, before any other Workbench script', () => {
    const absolutePath = path.join(scripts, 'workbenchRouter.js');
    const context = vm.createContext({});
    vm.runInContext(fs.readFileSync(absolutePath, 'utf8'), context, { filename: absolutePath });

    assert.equal(context.workbench.router.isRunning(), false);
});

test('a first page outside a repository has no repository id', () => {
    const harness = loadRouter();
    harness.session.url = 'https://example.test/workbench/';
    harness.start();

    assert.equal(harness.router.current().repositoryId, '');
});

for (const step of ['completeModel', 'loadScripts']) {
    test(`a navigation replaced while it waits in ${step} is abandoned`, async () => {
        const harness = loadRouter();
        harness.start();
        const waiting = deferred();
        const app = harness.workbench.app;
        const original = app[step];
        let calls = 0;
        app[step] = (...args) => (++calls === (step === 'loadScripts' ? 2 : 1) ? waiting.promise : original(...args));

        const first = harness.router.navigate(base + 'types', { history: 'push' });
        await harness.answer('types', harness.model('types'));
        harness.router.navigate(base + 'contexts', { history: 'push' });
        waiting.resolve();

        assert.equal(await first, 'abandoned');
        assert.deepEqual(harness.disposed, ['types']);
        assert.equal(harness.log.includes('mount types'), false);
    });
}

test('the router is not running until bootstrap starts it, and starts only once', () => {
    const harness = loadRouter();

    assert.equal(harness.router.isRunning(), false);
    harness.start();
    harness.start();

    assert.equal(harness.router.isRunning(), true);
    assert.equal(harness.document.listenerCount('click'), 1);
    assert.equal(harness.document.listenerCount('pointerover'), 1);
    assert.equal(harness.document.listenerCount('focusin'), 1);
    assert.equal(harness.window.listenerCount('popstate'), 1);
    assert.equal(harness.window.listenerCount('pagehide'), 1);
    assert.deepEqual({ ...harness.router.current() },
        { url: base + 'summary', viewId: 'summary', repositoryId: 'repo-1' });
    assert.equal(harness.outlet.getAttribute('data-workbench-route'), 'summary');
    assert.equal(harness.outlet.getAttribute('data-workbench-route-ready'), 'true');
});

test('only plain clicks on links to router-ready Workbench routes are handled in the page', () => {
    const harness = loadRouter();
    harness.register('query', { routerReady: false });
    harness.start();
    const cases = [
        [click(link(base + 'types')), true, 'a menu link'],
        [click(link(base + 'types', { target: '_self' })), true, 'target _self'],
        [click(link(base + 'export')), true, 'Export without a download'],
        [click(link(base + 'types'), { ctrlKey: true }), false, 'Ctrl'],
        [click(link(base + 'types'), { metaKey: true }), false, 'Meta'],
        [click(link(base + 'types'), { shiftKey: true }), false, 'Shift'],
        [click(link(base + 'types'), { altKey: true }), false, 'Alt'],
        [click(link(base + 'types'), { button: 1 }), false, 'middle button'],
        [click(link(base + 'types'), { defaultPrevented: true }), false, 'already handled'],
        [click(link(base + 'types', { download: '' })), false, 'download attribute'],
        [click(link(base + 'types', { target: '_blank' })), false, 'new tab'],
        [click(link(base + 'types', { rel: 'noopener external' })), false, 'external link'],
        [click(link('https://elsewhere.test/workbench/repositories/repo-1/types')), false, 'other origin'],
        [click(link('https://example.test/rdf4j-server/repositories/repo-1/types')), false, 'outside the Workbench'],
        [click(link(base + 'query')), false, 'a route that is not router-ready'],
        [click(link(base + 'unknown')), false, 'an unknown view'],
        [click(link(base + 'export?action=download&Accept=text%2Fturtle')), false, 'an export download'],
        [click(link(base + 'explore?Accept=text%2Fturtle')), false, 'an Accept parameter'],
        [click(link(base + 'summary#size')), false, 'a hash on the current page'],
        [click(null, { target: { closest: () => null } }), false, 'not on a link'],
        [click(null, { target: {} }), false, 'a target without closest()']
    ];
    for (const [event, handled, name] of cases) {
        const before = harness.loadModelCalls.length;
        harness.document.dispatch('click', event);
        assert.equal(event.defaultPrevented, handled || name === 'already handled', name);
        assert.equal(harness.loadModelCalls.length - before, handled ? 1 : 0, name);
    }
});

test('a page that is not router-ready is always left by a page load', () => {
    const harness = loadRouter({ href: base + 'query' });
    harness.register('query', { routerReady: false });
    harness.session.url = base + 'query';
    harness.start();

    const event = click(link(base + 'types'));
    harness.document.dispatch('click', event);

    assert.equal(event.defaultPrevented, false);
    assert.equal(harness.loadModelCalls.length, 0);
});

test('a newer navigation aborts the older one and its preloaded model is disposed', async () => {
    const harness = loadRouter();
    harness.start();

    const first = harness.router.navigate(base + 'types', { history: 'push' });
    const second = harness.router.navigate(base + 'contexts', { history: 'push' });
    assert.equal(harness.loadModelCalls[0].signal.aborted, true, 'the older request is aborted');
    await harness.answer('contexts', harness.model('contexts'));
    await harness.answer('types', harness.model('types'));

    assert.equal(await first, 'abandoned');
    assert.equal(await second, 'committed');
    assert.deepEqual(harness.disposed, ['types'], 'the abandoned model releases its rows');
    assert.equal(harness.log.filter((line) => line.startsWith('mount')).join(), 'mount contexts');
    assert.equal(harness.window.location.href, base + 'contexts');
});

test('the old page stays until the next one is ready, then the outlet swaps in one step', async () => {
    const harness = loadRouter();
    harness.register('types', { baseScripts: ['paging.js'], scripts: ['paging.js', 'types.js'] });
    harness.start();
    harness.window.scrollY = 640;

    const navigation = harness.router.navigate(base + 'types', { history: 'push' });
    assert.equal(harness.outlet.getAttribute('aria-busy'), 'true');
    assert.equal(harness.outlet.getAttribute('data-workbench-route-loading'), null, 'no progress bar at once');
    await new Promise((resolve) => setTimeout(resolve, 170));
    assert.equal(harness.outlet.getAttribute('data-workbench-route-loading'), 'true', 'a progress bar after 150 ms');
    assert.equal(harness.log.includes('dispose initial navigate'), false, 'the old page is still mounted');
    await harness.answer('types', harness.model('types'));

    assert.equal(await navigation, 'committed');
    assert.deepEqual(harness.log.slice(harness.log.indexOf('load types')), [
        'load types', 'scripts paging.js', 'scripts paging.js,types.js', 'dispose initial navigate',
        'namespaces types', 'render types', 'unbind context bar', 'bind context bar', 'mount types'
    ]);
    const firstKey = harness.window.history.entries[0][1].wbKey;
    assert.deepEqual(JSON.parse(JSON.stringify(harness.window.history.entries)), [
        ['replace', { wbKey: firstKey }, base + 'summary'],
        ['replace', { wbKey: firstKey, scrollY: 640 }, base + 'summary'],
        ['push', JSON.parse(JSON.stringify(harness.window.history.state)), base + 'types']
    ]);
    assert.equal(harness.window.history.state.scrollY, 0);
    assert.equal(typeof harness.window.history.state.wbKey, 'string');
    assert.deepEqual(harness.window.scrolledTo, [0]);
    assert.equal(harness.outlet.getAttribute('aria-busy'), null);
    assert.equal(harness.outlet.getAttribute('data-workbench-route-loading'), null);
    assert.equal(harness.outlet.getAttribute('data-workbench-route'), 'types');
    assert.equal(harness.outlet.getAttribute('data-workbench-route-ready'), 'true');
    assert.deepEqual({ ...harness.router.current() }, { url: base + 'types', viewId: 'types', repositoryId: 'repo-1' });
});

test('the page model request carries the abort signal', async () => {
    const harness = loadRouter();
    harness.start();

    harness.router.navigate(base + 'types', { history: 'push' });
    const call = harness.loadModelCalls[0];
    call.fetcher(base + 'info', { headers: { Accept: 'x' } });

    assert.equal(harness.fetched[0].fetchOptions.signal, call.signal);
    assert.equal(harness.fetched[0].fetchOptions.headers.Accept, 'x');
});

test('without AbortController a newer navigation still wins', async () => {
    const harness = loadRouter({ noAbortController: true });
    harness.start();

    const first = harness.router.navigate(base + 'types', { history: 'push' });
    harness.loadModelCalls[0].fetcher(base + 'types', {});
    const second = harness.router.navigate(base + 'contexts', { history: 'replace' });
    await harness.answer('types', harness.model('types'));
    await harness.answer('contexts', harness.model('contexts'));

    assert.equal(harness.loadModelCalls[0].signal, undefined);
    assert.deepEqual(harness.fetched[0].fetchOptions, {});
    assert.equal(await first, 'abandoned');
    assert.equal(await second, 'committed');
    assert.equal(harness.window.history.entries[2][0], 'replace', 'history: replace replaces the entry');
    assert.equal(harness.window.history.entries[2][2], base + 'contexts');
});

test('a model answered from a redirect is committed at its final URL', async () => {
    const harness = loadRouter();
    harness.start();

    const navigation = harness.router.navigate(base + 'types', { history: 'push' });
    await harness.answer('types', harness.model('types', { finalUrl: base + 'types?filter=Product' }));

    assert.equal(await navigation, 'committed');
    assert.equal(harness.window.location.href, base + 'types?filter=Product');
    assert.equal(harness.router.current().url, base + 'types?filter=Product');
});

test('a navigation abandoned by an abort commits nothing', async () => {
    const harness = loadRouter();
    harness.start();

    const navigation = harness.router.navigate(base + 'types', { history: 'push' });
    const abort = new Error('The operation was aborted.');
    abort.name = 'AbortError';
    await harness.fail('types', abort);

    assert.equal(await navigation, 'abandoned');
    assert.deepEqual(harness.window.assigned, []);
    assert.equal(harness.log.some((line) => line.startsWith('render')), false);
    assert.equal(harness.outlet.getAttribute('aria-busy'), null, 'the old page is usable again');
});

test('an unexpected failure is reported and falls back to a full page load', async () => {
    const harness = loadRouter();
    harness.start();

    const navigation = harness.router.navigate(base + 'types', { history: 'push' });
    const failure = new Error('boom');
    await harness.fail('types', failure);

    assert.equal(await navigation, 'fallback');
    assert.deepEqual(harness.window.assigned, [base + 'types']);
    // A page that cannot be shown in place is a bug (M12.1 found one in Explore); the console says why it reloaded.
    assert.equal(harness.consoleErrors.length, 1);
    assert.equal(harness.consoleErrors[0][harness.consoleErrors[0].length - 1], failure);
});

test('a failure after the model loaded releases the model before falling back', async () => {
    const harness = loadRouter();
    harness.start();
    harness.workbench.app.completeModel = () => Promise.reject(new Error('linked info failed'));

    const navigation = harness.router.navigate(base + 'types', { history: 'push' });
    await harness.answer('types', harness.model('types'));

    assert.equal(await navigation, 'fallback');
    assert.deepEqual(harness.disposed, ['types']);
});

test('a route that is not router-ready is loaded by the browser', async () => {
    const harness = loadRouter();
    harness.register('query', { routerReady: false });
    harness.start();

    assert.equal(await harness.router.navigate(base + 'query', { history: 'push' }), 'fallback');
    assert.deepEqual(harness.window.assigned, [base + 'query']);
});

test('an error answer is shown inside the shell instead of reloading', async () => {
    const harness = loadRouter();
    harness.start();

    const navigation = harness.router.navigate(base + 'types', { history: 'push' });
    await harness.answer('types', harness.model('types', { error: { status: 500, code: '', message: 'Store closed' } }));

    assert.equal(await navigation, 'committed');
    assert.ok(harness.log.includes('render types'), 'the views render the error callout');
    assert.equal(harness.log.includes('mount types'), false, 'an error page mounts no route');
    assert.equal(harness.log.includes('namespaces types'), false);
    assert.equal(harness.log.filter((line) => line.startsWith('scripts')).length, 1,
        'an error page loads no model-dependent scripts');
    assert.equal(harness.window.location.href, base + 'types');
    assert.equal(harness.outlet.getAttribute('data-workbench-route-ready'), 'true');
    harness.router.navigate(base + 'contexts', { history: 'push' });
    await harness.answer('contexts', harness.model('contexts'));
    assert.deepEqual(harness.disposed, ['types'], 'leaving the error page releases its rows');
    assert.equal(harness.router.current().viewId, 'contexts');
});

test('a route that mounts asynchronously and settles after the next navigation is disposed', async () => {
    const harness = loadRouter();
    const mounting = deferred();
    harness.register('types', { mounted: mounting.promise });
    harness.start();

    const first = harness.router.navigate(base + 'types', { history: 'push' });
    await harness.answer('types', harness.model('types'));
    assert.equal(await first, 'committed');
    assert.equal(harness.outlet.getAttribute('data-workbench-route-ready'), 'false', 'not ready while it mounts');
    harness.router.navigate(base + 'contexts', { history: 'push' });
    await harness.answer('contexts', harness.model('contexts'));
    mounting.resolve();
    await settle();

    assert.ok(harness.log.includes('dispose types navigate'));
    assert.equal(harness.outlet.getAttribute('data-workbench-route'), 'contexts');
    assert.equal(harness.outlet.getAttribute('data-workbench-route-ready'), 'true');
});

test('a route that becomes ready after the next navigation does not mark the outlet', async () => {
    const harness = loadRouter();
    const ready = deferred();
    harness.register('types', { ready: ready.promise });
    harness.start();

    harness.router.navigate(base + 'types', { history: 'push' });
    await harness.answer('types', harness.model('types'));
    const next = harness.router.navigate(base + 'contexts', { history: 'push' });
    ready.resolve();
    await settle();
    assert.equal(harness.outlet.getAttribute('data-workbench-route'), 'types');
    assert.equal(harness.outlet.getAttribute('data-workbench-route-ready'), 'false');
    assert.equal(harness.outlet.getAttribute('aria-busy'), 'true', 'the newer navigation is still running');
    await harness.answer('contexts', harness.model('contexts'));
    await next;

    assert.ok(harness.log.includes('dispose types navigate'));
    assert.equal(harness.outlet.getAttribute('data-workbench-route'), 'contexts');
});

test('Back and Forward navigate in the page, and reload routes the router cannot show', async () => {
    const harness = loadRouter();
    harness.register('query', { routerReady: false });
    harness.start();
    const navigation = harness.router.navigate(base + 'types', { history: 'push' });
    await harness.answer('types', harness.model('types'));
    await navigation;
    const entries = harness.window.history.entries.length;

    harness.window.goTo(base + 'summary', harness.window.history.entries[0][1]);
    harness.window.dispatch('popstate', { state: null });
    await harness.answer('summary', harness.model('summary'));
    assert.equal(harness.router.current().viewId, 'summary');
    assert.equal(harness.window.history.entries.length, entries, 'Back changes no history entry');

    harness.window.goTo(base + 'summary#size');
    harness.window.dispatch('popstate', { state: null });
    assert.equal(harness.loadModelCalls.length, 2, 'a hash change on the same page is not a navigation');

    harness.window.goTo(base + 'query');
    harness.window.dispatch('popstate', { state: null });
    assert.equal(harness.window.reloaded, 1);
});

